<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/App.php';

use UPS\{App,ApiError,Service};

$passed=[];
function check(bool $condition,string $message): void { if(!$condition){throw new RuntimeException($message);} }
function fails(int $status,callable $call): void {try{$call();}catch(ApiError $e){check($e->status===$status,'unexpected API status');return;}throw new RuntimeException('unsafe request accepted');}
function fixture(): array {
    $dir=sys_get_temp_dir().'/ups-backend-test-'.bin2hex(random_bytes(8));mkdir($dir,0700);
    $secret=bin2hex(random_bytes(32));$now=1792436400;
    $app=new App(['storage_dir'=>$dir,'bootstrap_hash'=>hash('sha256',$secret),'public_url'=>'https://ups.example/api/v1']);
    $owner=$app->handle('POST','/bootstrap',$secret,['name'=>'Test workspace'],[],'test-peer',$now);
    return [$app,$owner,$now,$dir,$secret];
}
function paired(App $app,string $owner,int $now,string $name='Pi'): array {
    $p=$app->handle('POST','/pairings',$owner,['name'=>$name],[],'owner-peer',$now);
    return $app->handle('POST','/pairings/claim','',['code'=>$p['pairing_code'],'agent_id'=>Service::uuid()],[],'claim-'.Service::uuid(),$now);
}
function packet(string $agent,int $sequence,int $now,string $status='OL',string $battery='100'): array {
    $source=str_repeat('a',64);$device=str_repeat('b',64);$date=gmdate('Y-m-d\TH:i:s\Z',$now);
    return ['schema_version'=>1,'agent_id'=>$agent,'messages'=>[[
        'schema_version'=>1,'agent_id'=>$agent,'id'=>Service::uuid(),'sequence'=>$sequence,'recorded_at'=>$date,
        'sources'=>[['source_id'=>$source,'name'=>'Office','connection'=>'reachable','discovered_ups'=>['ups_office']]],
        'readings'=>[['source_id'=>$source,'device_id'=>$device,'ups_key'=>'ups_office','observed_at'=>$date,'variables'=>['ups.status'=>$status,'battery.charge'=>$battery,'ups.load'=>'5','ups.realpower.nominal'=>'810'],'power_watts'=>999,'power_estimated'=>true]],
        'events'=>[],'dropped_messages_total'=>0,
    ]]];
}
function upload(App $app,array $agent,array $body,int $now): array {return $app->handle('POST','/ingest',$agent['agent_token'],$body,[],'agent-peer',$now);}
function state(App $app,array $owner,array $agent,int $now): array {return $app->handle('GET','/agents/'.$agent['agent_id'].'/state',$owner['owner_token'],[],[],'owner-peer',$now);}
function countRows(App $app,string $table): int {return (int)$app->service->db->pdo->query('SELECT count(*) FROM '.$table)->fetchColumn();}
function test(string $name,callable $action): void {global $passed;$action();$passed[]=$name;echo "PASS ".$name."\n";}

test('bootstrap is authenticated and one-time',function(){[$a,$o,$n,$dir,$secret]=fixture();fails(409,fn()=>$a->handle('POST','/bootstrap',$secret,['name'=>'Other'],[],'p',$n));fails(401,fn()=>$a->handle('POST','/bootstrap','incorrect',['name'=>'Other'],[],'p',$n));check(!str_contains(file_get_contents($dir.'/monitor.sqlite'),$o['owner_token']),'raw owner token stored');});
test('separate roles and private state',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);fails(401,fn()=>$a->handle('GET','/agents','',[],[],'p',$n));fails(401,fn()=>$a->handle('POST','/ingest',$o['owner_token'],packet($agent['agent_id'],1,$n),[],'p',$n));fails(401,fn()=>$a->handle('GET','/agents',$agent['agent_token'],[],[],'p',$n));fails(401,fn()=>$a->handle('POST','/admin/workspaces',$o['owner_token'],['name'=>'Other'],[],'p',$n));});
test('tenant isolation for state history events and revocation',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$other=$a->handle('POST','/admin/workspaces',$o['admin_token'],['name'=>'Other'],[],'admin',$n);foreach(['state','history','events'] as $path){fails(404,fn()=>$a->handle('GET','/agents/'.$agent['agent_id'].'/'.$path,$other['owner_token'],[],['device_id'=>str_repeat('b',64)],'other',$n));}fails(404,fn()=>$a->handle('POST','/agents/'.$agent['agent_id'].'/revoke',$other['owner_token'],[],[],'other',$n));});
test('pairings expire and cannot be reused or taken over',function(){[$a,$o,$n]=fixture();$p=$a->handle('POST','/pairings',$o['owner_token'],['name'=>'Pi'],[],'p',$n);$id=Service::uuid();$a->handle('POST','/pairings/claim','',['code'=>$p['pairing_code'],'agent_id'=>$id],[],'p',$n);fails(401,fn()=>$a->handle('POST','/pairings/claim','',['code'=>$p['pairing_code'],'agent_id'=>Service::uuid()],[],'p',$n));$p=$a->handle('POST','/pairings',$o['owner_token'],['name'=>'Pi'],[],'p',$n);fails(401,fn()=>$a->handle('POST','/pairings/claim','',['code'=>$p['pairing_code'],'agent_id'=>Service::uuid()],[],'p',$n+601));$other=$a->handle('POST','/admin/workspaces',$o['admin_token'],['name'=>'Other'],[],'p',$n);$p=$a->handle('POST','/pairings',$other['owner_token'],['name'=>'Pi'],[],'p',$n);fails(409,fn()=>$a->handle('POST','/pairings/claim','',['code'=>$p['pairing_code'],'agent_id'=>$id],[],'p',$n));});
test('invalid pairing attempts consume rate budget',function(){[$a,$o,$n]=fixture();for($i=0;$i<8;$i++){fails(401,fn()=>$a->handle('POST','/pairings/claim','',['code'=>'0000-0000-0000-0000','agent_id'=>Service::uuid()],[],'same-peer',$n));}fails(429,fn()=>$a->handle('POST','/pairings/claim','',['code'=>'0000-0000-0000-0000','agent_id'=>Service::uuid()],[],'same-peer',$n));});
test('Go-compatible receipt power estimate and optional metrics',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=packet($agent['agent_id'],1,$n);$receipt=upload($a,$agent,$p,$n);check($receipt['acknowledged_ids']===[$p['messages'][0]['id']],'wrong acknowledgement');$s=state($a,$o,$agent,$n);$r=$s['devices'][0]['reading'];check($r['power_watts']===40.5&&$r['power_estimated']===true,'estimate is not computed from NUT');check(!isset($r['variables']['output.voltage']),'missing voltage invented');check(!$s['devices'][0]['stale'],'live data incorrectly stale');});
test('measured power takes priority',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=packet($agent['agent_id'],1,$n);$p['messages'][0]['readings'][0]['variables']['ups.realpower']='36.25';upload($a,$agent,$p,$n);$r=state($a,$o,$agent,$n)['devices'][0]['reading'];check($r['power_watts']===36.25&&!$r['power_estimated'],'measurement ignored');});
test('duplicate retries do not duplicate history or events',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=packet($agent['agent_id'],1,$n,'OB','87');$p['messages'][0]['events']=[['id'=>Service::uuid(),'kind'=>'on_battery','source_id'=>str_repeat('a',64),'device_id'=>str_repeat('b',64),'observed_at'=>gmdate('Y-m-d\TH:i:s\Z',$n)]];upload($a,$agent,$p,$n);$samples=countRows($a,'samples');upload($a,$agent,$p,$n+1);check(countRows($a,'messages')===1&&countRows($a,'samples')===$samples&&countRows($a,'events')===1,'duplicate side effects');});
test('mutated message or sequence is rejected',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=packet($agent['agent_id'],1,$n);upload($a,$agent,$p,$n);$p['messages'][0]['readings'][0]['variables']['battery.charge']='9';fails(409,fn()=>upload($a,$agent,$p,$n));fails(409,fn()=>upload($a,$agent,packet($agent['agent_id'],1,$n),$n));});
test('batch rollback is all or nothing',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=packet($agent['agent_id'],1,$n);upload($a,$agent,$p,$n);$bad=$p['messages'][0];$bad['readings'][0]['variables']['battery.charge']='9';$new=packet($agent['agent_id'],2,$n+1);$new['messages'][]=$bad;fails(409,fn()=>upload($a,$agent,$new,$n+1));check(countRows($a,'messages')===1,'failed batch committed some receipts');check(state($a,$o,$agent,$n)['devices'][0]['reading']['variables']['battery.charge']==='100','failed batch changed current state');});
test('credentials and unknown variables never enter storage',function(){[$a,$o,$n,$dir]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=packet($agent['agent_id'],1,$n);$p['messages'][0]['readings'][0]['variables']['driver.password']='NEVER-PERSIST-ME';fails(422,fn()=>upload($a,$agent,$p,$n));check(countRows($a,'messages')===0&&!str_contains(file_get_contents($dir.'/monitor.sqlite'),'NEVER-PERSIST-ME'),'credential stored');});
test('wrong agent and device identities are rejected',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);fails(422,fn()=>upload($a,$agent,packet(Service::uuid(),1,$n),$n));$p=packet($agent['agent_id'],1,$n);upload($a,$agent,$p,$n);$p=packet($agent['agent_id'],2,$n+1);$p['messages'][0]['readings'][0]['ups_key']='different-ups';fails(409,fn()=>upload($a,$agent,$p,$n+1));});
test('out-of-order history never rolls back current state',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);upload($a,$agent,packet($agent['agent_id'],2,$n,'OB','87'),$n);upload($a,$agent,packet($agent['agent_id'],1,$n-60,'OL','100'),$n+1);$s=state($a,$o,$agent,$n+1);check($s['last_sequence']===2&&$s['devices'][0]['reading']['variables']['battery.charge']==='87','old request replaced new state');check(countRows($a,'samples')===2,'old history was discarded');});
test('offline snapshots preserve timestamp and freeze metrics',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=packet($agent['agent_id'],1,$n);upload($a,$agent,$p,$n);$offline=packet($agent['agent_id'],2,$n+10);$offline['messages'][0]['sources'][0]['connection']='unavailable';$offline['messages'][0]['sources'][0]['discovered_ups']=null;$offline['messages'][0]['readings']=null;$offline['messages'][0]['last_known_readings']=$p['messages'][0]['readings'];upload($a,$agent,$offline,$n+10);$s=state($a,$o,$agent,$n+10);check($s['devices'][0]['stale']&&$s['devices'][0]['reading']['observed_at']===$p['messages'][0]['readings'][0]['observed_at'],'offline timestamp changed');upload($a,$agent,packet($agent['agent_id'],3,$n+11,'OL','98'),$n+11);check(!state($a,$o,$agent,$n+11)['devices'][0]['stale'],'reconnection failed');});
test('missing heartbeat and clock skew mark data stale without fabricating outage',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);upload($a,$agent,packet($agent['agent_id'],1,$n),$n);$s=state($a,$o,$agent,$n+91);check(!$s['agent_available']&&$s['devices'][0]['stale']&&countRows($a,'events')===0,'agent silence invented outage');upload($a,$agent,packet($agent['agent_id'],2,$n+600),$n);check(state($a,$o,$agent,$n)['devices'][0]['clock_skew'],'future timestamp shown as live');});
test('short power transitions survive minute history downsampling',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$n=intdiv($n,60)*60;upload($a,$agent,packet($agent['agent_id'],1,$n),$n);foreach([[2,'OB','87','on_battery'],[3,'OL','87','power_restored']] as [$seq,$status,$battery,$event]){$p=packet($agent['agent_id'],$seq,$n+$seq*3,$status,$battery);$p['messages'][0]['events']=[['id'=>Service::uuid(),'kind'=>$event,'source_id'=>str_repeat('a',64),'device_id'=>str_repeat('b',64),'observed_at'=>gmdate('Y-m-d\TH:i:s\Z',$n+$seq*3)]];upload($a,$agent,$p,$n+$seq*3);}check(countRows($a,'samples')===3&&countRows($a,'events')===2,'short outage lost in history');});
test('history pagination and bounded queries',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);for($i=1;$i<=3;$i++){upload($a,$agent,packet($agent['agent_id'],$i,$n+$i*60),$n+$i*60);}$path='/agents/'.$agent['agent_id'].'/history';$q=['device_id'=>str_repeat('b',64),'limit'=>'1'];$page=$a->handle('GET',$path,$o['owner_token'],[],$q,'p',$n+180);check(count($page['items'])===1&&$page['next_cursor']!==null,'pagination missing');$q['cursor']=(string)$page['next_cursor'];$next=$a->handle('GET',$path,$o['owner_token'],[],$q,'p',$n+180);check($next['items'][0]['cursor']>$page['items'][0]['cursor'],'cursor repeated');fails(422,fn()=>$a->handle('GET',$path,$o['owner_token'],[],['device_id'=>str_repeat('b',64),'limit'=>'100000'],'p',$n));});
test('revoked and rotated credentials stop ingestion',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);$p=$a->handle('POST','/pairings',$o['owner_token'],['name'=>'Pi'],[],'p',$n);$new=$a->handle('POST','/pairings/claim','',['code'=>$p['pairing_code'],'agent_id'=>$agent['agent_id']],[],'p',$n);fails(401,fn()=>upload($a,$agent,packet($agent['agent_id'],1,$n),$n));upload($a,$new,packet($new['agent_id'],1,$n),$n);$a->handle('POST','/agents/'.$new['agent_id'].'/revoke',$o['owner_token'],[],[],'p',$n);fails(401,fn()=>upload($a,$new,packet($new['agent_id'],2,$n),$n));});
test('retention excludes expired history and permits latest cached reading',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);upload($a,$agent,packet($agent['agent_id'],1,$n-8*86400),$n);check(countRows($a,'samples')===0&&count(state($a,$o,$agent,$n)['devices'])===1,'retention erased last known state or retained expired history');});
test('workspace deletion cascades and invalidates credentials',function(){[$a,$o,$n]=fixture();$agent=paired($a,$o['owner_token'],$n);upload($a,$agent,packet($agent['agent_id'],1,$n),$n);$a->handle('DELETE','/workspace',$o['owner_token'],[],[],'p',$n);foreach(['agents','messages','sources','devices','samples','events','pairings'] as $table){check(countRows($a,$table)===0,'tenant data not removed');}fails(401,fn()=>upload($a,$agent,packet($agent['agent_id'],2,$n),$n));});


test('mobile pairing is one-time private scoped and expiring',function(){[$a,$o,$n,$dir]=fixture();$agent=paired($a,$o['owner_token'],$n);upload($a,$agent,packet($agent['agent_id'],1,$n),$n);$p=$a->handle('POST','/mobile-pairings',$o['owner_token'],[],[],'p',$n);$phone=$a->handle('POST','/mobile-pairings/claim','',['code'=>$p['pairing_code']],[],'p',$n);$token=$phone['access_token'];check(str_starts_with($token,'ups_mobile_'),'wrong token role');check(count($a->handle('GET','/agents',$token,[],[],'p',$n)['agents'])===1,'phone cannot read agents');fails(401,fn()=>$a->handle('POST','/mobile-pairings/claim','',['code'=>$p['pairing_code']],[],'p',$n));foreach([['DELETE','/workspace'],['POST','/mobile-pairings'],['POST','/agents/'.$agent['agent_id'].'/revoke']] as [$method,$path]){fails(403,fn()=>$a->handle($method,$path,$token,[],[],'p',$n));}fails(401,fn()=>upload($a,['agent_token'=>$token,'agent_id'=>$agent['agent_id']],packet($agent['agent_id'],2,$n),$n));$other=$a->handle('POST','/admin/workspaces',$o['admin_token'],['name'=>'Other'],[],'p',$n);$second=paired($a,$other['owner_token'],$n);fails(404,fn()=>$a->handle('GET','/agents/'.$second['agent_id'].'/state',$token,[],[],'p',$n));check(!str_contains(file_get_contents($dir.'/monitor.sqlite'),$token),'raw mobile token stored');fails(401,fn()=>$a->handle('GET','/agents',$token,[],[],'p',$n+91*86400));});
test('phone can link an agent and revoke only its own session',function(){[$a,$o,$n]=fixture();$p=$a->handle('POST','/mobile-pairings',$o['owner_token'],[],[],'p',$n);$phone=$a->handle('POST','/mobile-pairings/claim','',['code'=>$p['pairing_code']],[],'p',$n);$a->handle('POST','/pairings',$phone['access_token'],['name'=>'Pi'],[],'p',$n);fails(403,fn()=>$a->handle('DELETE','/mobile-sessions/'.$phone['session_id'],$phone['access_token'],[],[],'p',$n));$a->handle('DELETE','/mobile-session',$phone['access_token'],[],[],'p',$n);fails(401,fn()=>$a->handle('GET','/agents',$phone['access_token'],[],[],'p',$n));});
test('mobile code expiry and owner revocation',function(){[$a,$o,$n]=fixture();$p=$a->handle('POST','/mobile-pairings',$o['owner_token'],[],[],'p',$n);fails(401,fn()=>$a->handle('POST','/mobile-pairings/claim','',['code'=>$p['pairing_code']],[],'p',$n+601));$p=$a->handle('POST','/mobile-pairings',$o['owner_token'],[],[],'p',$n);$phone=$a->handle('POST','/mobile-pairings/claim','',['code'=>$p['pairing_code']],[],'p',$n);$a->handle('DELETE','/mobile-sessions/'.$phone['session_id'],$o['owner_token'],[],[],'p',$n);fails(401,fn()=>$a->handle('GET','/agents',$phone['access_token'],[],[],'p',$n));});
test('schema v1 upgrades without changing owner or readings',function(){[$a,$o,$n,$dir]=fixture();$agent=paired($a,$o['owner_token'],$n);upload($a,$agent,packet($agent['agent_id'],1,$n),$n);unset($a);$old=new PDO('sqlite:'.$dir.'/monitor.sqlite');$old->exec('DROP TABLE mobile_sessions; DROP TABLE mobile_pairings; PRAGMA user_version=1');unset($old);$b=new App(['storage_dir'=>$dir,'public_url'=>'https://ups.example/api/v1']);check((int)$b->service->db->pdo->query('PRAGMA user_version')->fetchColumn()===2,'migration missing');check(count($b->handle('GET','/agents',$o['owner_token'],[],[],'p',$n)['agents'])===1,'owner lost during migration');check(count(state($b,$o,$agent,$n)['devices'])===1,'reading lost during migration');});
echo json_encode(['passed'=>count($passed),'failed'=>0,'scenarios'=>$passed],JSON_PRETTY_PRINT)."\n";
